import java.util.*;
import java.io.*;

public class Main {
    static List<String> analyze(char[] s, int[] queries) {
        // Write your solution here
        // Return the loss for each query, then the final line "bestDay bestLoss".
        return new ArrayList<>();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        char[] s = new char[n];
        for (int i = 0; i < n; i++) s[i] = st.nextToken().charAt(0);
        int q = Integer.parseInt(st.nextToken());
        int[] queries = new int[q];
        for (int i = 0; i < q; i++) queries[i] = Integer.parseInt(st.nextToken());
        StringBuilder sb = new StringBuilder();
        for (String line : analyze(s, queries)) sb.append(line).append('\n');
        System.out.print(sb);
    }
}
